node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check cart schema and data
console.log('=== CARTS SCHEMA ===');
const cartCols = db.prepare(\"PRAGMA table_info(carts)\").all();
console.log(cartCols.map(c => c.name + ' (' + c.type + ')'));

console.log('\n=== CARTS DATA ===');
const carts = db.prepare('SELECT * FROM carts').all();
console.log(JSON.stringify(carts, null, 2));

console.log('\n=== CART_ITEMS SCHEMA ===');
const ciCols = db.prepare(\"PRAGMA table_info(cart_items)\").all();
console.log(ciCols.map(c => c.name + ' (' + c.type + ')'));

console.log('\n=== CART_ITEMS DATA ===');
const cartItems = db.prepare('SELECT * FROM cart_items').all();
console.log(JSON.stringify(cartItems, null, 2));

console.log('\n=== PROMOTIONS SCHEMA ===');
const promoCols = db.prepare(\"PRAGMA table_info(promotions)\").all();
console.log(promoCols.map(c => c.name + ' (' + c.type + ')'));

console.log('\n=== PROMOTIONS DATA ===');
const promos = db.prepare('SELECT * FROM promotions').all();
console.log(JSON.stringify(promos, null, 2));

db.close();
"

